// Simular Intersection Observer con un objeto mock
// (en el sandbox no hay DOM real, así que simulamos el comportamiento)

function crearIntersectionObserverMock() {
  const callbacks = new Map();
  const observados = new Set();

  return {
    observe(elemento) {
      observados.add(elemento);
    },
    unobserve(elemento) {
      observados.delete(elemento);
    },
    disconnect() {
      observados.clear();
    },
    // Simula que un elemento entra al viewport:
    _simularEntrada(elemento) {
      callbacks.forEach(cb => cb([{
        target: elemento,
        isIntersecting: true,
        intersectionRatio: 1,
      }]));
    },
    _registrarCallback(cb) {
      callbacks.set(Symbol(), cb);
    },
  };
}

// Simula lazy loading
const observer = crearIntersectionObserverMock();
const imagenesSimuladas = [
  { id: 'img1', dataSrc: 'foto1.jpg', src: null },
  { id: 'img2', dataSrc: 'foto2.jpg', src: null },
];

function onIntersect(entries) {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.src = entry.target.dataSrc;
      console.log(`Cargando: ${entry.target.id}`);
      observer.unobserve(entry.target);
    }
  });
}

observer._registrarCallback(onIntersect);
imagenesSimuladas.forEach(img => observer.observe(img));
observer._simularEntrada(imagenesSimuladas[0]);
console.log('img1.src:', imagenesSimuladas[0].src);
console.log('img2.src:', imagenesSimuladas[1].src);

// Patrón: usar Intersection Observer con cleanup
function observarConAnimacion(elementos, claseVisible) {
  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add(claseVisible);
          // Opcionalmente: deja de observar una vez que animó
          // observer.unobserve(entry.target);
        }
      });
    },
    { threshold: 0.15 }
  );

  elementos.forEach(el => observer.observe(el));

  // Retorna función de cleanup
  return () => observer.disconnect();
}

