// Mock de IntersectionObserver para el sandbox
const elementos = [
  { id: 'el-1' },
  { id: 'el-2' },
  { id: 'el-3' },
];

const entrados = [];
let totalObservados = 0;

// Simula el callback del observer
function onIntersect(entries) {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entrados.push(entry.target.id);
    }
  });
}

// Simula observe() para cada elemento
elementos.forEach(el => totalObservados++);

// Simula las notificaciones del observer
onIntersect([
  { target: elementos[0], isIntersecting: true,  intersectionRatio: 1 },
  { target: elementos[1], isIntersecting: false, intersectionRatio: 0 },
  { target: elementos[2], isIntersecting: true,  intersectionRatio: 0.8 },
]);

console.log('Entrados:', entrados);
console.log('Total observados:', totalObservados);

function crearLazyLoader(onCargar) {
  const pendientes = new Set();

  return {
    agregar(elemento) {
      pendientes.add(elemento);
    },
    simularVisibilidad(elemento) {
      if (pendientes.has(elemento)) {
        onCargar(elemento);
        pendientes.delete(elemento);
      }
    },
    get pendienteCount() {
      return pendientes.size;
    },
  };
}

const cargados = [];
const loader = crearLazyLoader(el => cargados.push(el.id));

const imgs = [{ id: 'img1' }, { id: 'img2' }, { id: 'img3' }];
imgs.forEach(img => loader.agregar(img));

const pendientesAntes = loader.pendienteCount; // 3

loader.simularVisibilidad(imgs[0]); // Carga img1
loader.simularVisibilidad(imgs[0]); // Segunda vez — no debe cargar de nuevo
loader.simularVisibilidad(imgs[2]); // Carga img3

const pendientesDespues = loader.pendienteCount; // 1 (solo img2)
const cargadosTotal = cargados.length;           // 2 (img1 y img3)

console.log('Antes:', pendientesAntes, '| Después:', pendientesDespues);
console.log('Cargados:', cargados);

function crearAnalytics() {
  const historial = new Map(); // id → [ratios]
  const vistosUnaVez = new Set();
  const vistosCompletos = new Set();
  let tiempoTotal = 0;

  return {
    registrar(id) {
      if (!historial.has(id)) historial.set(id, []);
    },
    reportarVisibilidad(id, ratio) {
      if (!historial.has(id)) historial.set(id, []);
      historial.get(id).push(ratio);
      tiempoTotal++;

      if (ratio > 0)   vistosUnaVez.add(id);
      if (ratio >= 0.9) vistosCompletos.add(id);
    },
    getReporte() {
      return {
        vistosUnaVez,
        vistosCompletos,
        tiempoTotal,
        promedioRatio(id) {
          const ratios = historial.get(id) ?? [];
          if (ratios.length === 0) return 0;
          return ratios.reduce((a, b) => a + b, 0) / ratios.length;
        },
      };
    },
  };
}

const analytics = crearAnalytics();

analytics.registrar('banner');
analytics.registrar('producto-1');
analytics.registrar('footer');

// Simular reportes de visibilidad
analytics.reportarVisibilidad('banner', 1.0);
analytics.reportarVisibilidad('banner', 0.8);
analytics.reportarVisibilidad('banner', 0.6);
analytics.reportarVisibilidad('producto-1', 0);
analytics.reportarVisibilidad('footer', 0.95);

const reporte = analytics.getReporte();
const promedioBanner = reporte.promedioRatio('banner');
const tieneFooterCompleto = reporte.vistosCompletos.has('footer');
const noVioProducto1 = !reporte.vistosUnaVez.has('producto-1');

console.log('Visto 1 vez:', [...reporte.vistosUnaVez]);
console.log('Visto completo:', [...reporte.vistosCompletos]);
console.log('Promedio banner:', promedioBanner.toFixed(2));
